mapper.select:
select
bcci.id,
bcci.api_code,
bcci.cust_num as custNum,
DATE_FORMAT(bcci.create_time, '%Y-%m-%d') as appletDate,
bcci.clue_id as clueId,
bcci.clue_data_status as clueDataStatus,
bcci.clue_complete_status as clueCompleteStatus,
bcci.intention,
bcci.brand,
bcci.series,
bcci.city,
bcci.cell,
DATE_FORMAT(bcci.clean_time, '%Y-%m-%d %H:%i:%s') as cleanTime,
DATE_FORMAT(bcci.update_time, '%Y-%m-%d %H:%i:%s') as updateTime,
bcci.clue_push_channel as cluePushChannel,
bcci.clue_push_status as cluePushStatus,
DATE_FORMAT(bcci.push_time, '%Y-%m-%d %H:%i:%s') as pushTime,
DATE_FORMAT(bcci.call_back_time, '%Y-%m-%d %H:%i:%s') as callBackTime,
bcci.clue_callback_final_state as clueCallbackFinalState,
bcci.recording_path as recordingPath
from b_car_clue_info bcci


         and bcci.create_time >= #{createTimeStart} 


         and bcci.create_time < #{createTimeEnd} 


        and bcci.intention = #{intention}


        AND bcci.clue_data_status IN

            #{clueDataStatus}



         and bcci.update_time >= #{updateTimeStart} 


         and bcci.update_time < #{updateTimeEnd} 


        AND (bcci.clue_push_channel IS NULL OR bcci.clue_push_channel = '')


        AND bcci.clue_push_channel IN

            #{channel}



        and bcci.clue_push_status = #{cluePushStatus}


         and bcci.push_time >= #{pushTimeStart} 


         and bcci.push_time < #{pushTimeEnd} 


        and bcci.clue_callback_final_state = #{status}


         and bcci.call_back_time >= #{callBackTimeStart} 


         and bcci.call_back_time < #{callBackTimeEnd} 


        and (bcci.brand like concat("%", #{search},"%")
        or bcci.series like concat("%", #{search},"%")
        or bcci.city like concat("%", #{search},"%"))


order by bcci.create_time desc

update.foreach:
UPDATE b_car_clue_info
SET
brand = #{item.brand, jdbcType=VARCHAR},
series = #{item.series, jdbcType=VARCHAR},
update_time = #{item.updateTime, jdbcType=TIMESTAMP}
WHERE id = #{item.id}
